import{_ as i,D as t,h as n,c as l,b as e,e as o,G as r,ab as d}from"./chunks/framework.DJ821DkN.js";const b=JSON.parse('{"title":"Format Overview","description":"TOON syntax with concrete examples – objects, arrays, tabular headers, comments, and quoting rules.","frontmatter":{"description":"TOON syntax with concrete examples – objects, arrays, tabular headers, comments, and quoting rules."},"headers":[],"relativePath":"en/guide/format-overview.md","filePath":"guide/format-overview.md","lastUpdated":1784854192000}'),p={name:"en/guide/format-overview.md"};function h(c,s,k,y,u,g){const a=t("CopyOrDownloadAsMarkdownButtons");return n(),l("div",null,[s[0]||(s[0]=e("div",{style:{display:"none"},hidden:"true","aria-hidden":"true","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /en/guide/format-overview.md for this page in Markdown format",-1)),s[1]||(s[1]=e("h1",{id:"format-overview",tabindex:"-1"},[o("Format Overview "),e("a",{class:"header-anchor",href:"#format-overview","aria-label":'Permalink to "Format Overview"'},"​")],-1)),r(a),s[2]||(s[2]=d(`<p>TOON syntax reference with concrete examples. See <a href="/guide/getting-started.html">Getting Started</a> for an introduction.</p><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><p>TOON models data the same way as JSON:</p><ul><li><strong>Primitives</strong>: strings, numbers, booleans, and <code>null</code></li><li><strong>Objects</strong>: mappings from string keys to values</li><li><strong>Arrays</strong>: ordered sequences of values</li></ul><h3 id="root-forms" tabindex="-1">Root Forms <a class="header-anchor" href="#root-forms" aria-label="Permalink to &quot;Root Forms&quot;">​</a></h3><p>A TOON document can represent different root forms:</p><ul><li><strong>Root object</strong> (most common): Fields appear at depth 0 with no parent key</li><li><strong>Root array</strong>: Begins with <code>[N]:</code> or <code>[N]{fields}:</code> at depth 0</li><li><strong>Root primitive</strong>: A single primitive value (string, number, boolean, or null)</li></ul><p>Most examples in these docs use root objects, but the format supports all three forms equally (<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#5-concrete-syntax-and-root-form" target="_blank" rel="noreferrer">spec §5</a>).</p><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><h3 id="simple-objects" tabindex="-1">Simple Objects <a class="header-anchor" href="#simple-objects" aria-label="Permalink to &quot;Simple Objects&quot;">​</a></h3><p>Objects with primitive values use <code>key: value</code> syntax, with one field per line:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">active</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Indentation replaces braces. One space follows the colon.</p><h3 id="nested-objects" tabindex="-1">Nested Objects <a class="header-anchor" href="#nested-objects" aria-label="Permalink to &quot;Nested Objects&quot;">​</a></h3><p>Nested objects add one indentation level (default: 2 spaces):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span></code></pre></div><p>When a key ends with <code>:</code> and has no value on the same line, it opens a nested object. All lines at the next indentation level belong to that object.</p><h3 id="empty-objects" tabindex="-1">Empty Objects <a class="header-anchor" href="#empty-objects" aria-label="Permalink to &quot;Empty Objects&quot;">​</a></h3><p>An empty object at the root yields an empty document (no lines). A nested empty object is <code>key:</code> alone, with no children.</p><h3 id="keyed-tabular-objects" tabindex="-1">Keyed Tabular Objects <a class="header-anchor" href="#keyed-tabular-objects" aria-label="Permalink to &quot;Keyed Tabular Objects&quot;">​</a></h3><p>When an object has at least two entries whose values are uniform objects (same keys, primitive or nested-uniform values), it collapses into a keyed tabular form: the shared field structure appears once in the header, and each entry becomes one row that carries its own key:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2:]{age,city}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  alice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30,Berlin</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">25,Paris</span></span></code></pre></div><p>The colon immediately after the length (<code>[2:]</code>) marks the keyed header, and <code>[N]</code> declares the entry count. Each entry row is <code>entrykey: cell,cell,…</code> – the entry key followed by the entry value&#39;s leaf values in field order.</p><p>When the root object itself is eligible, the key is omitted:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2:]{age,city}:</span></span>
<span class="line"><span>  alice: 30,Berlin</span></span>
<span class="line"><span>  bob: 25,Paris</span></span></code></pre></div><p>Objects that don&#39;t qualify keep the nested form unchanged: single-entry objects, objects whose values mix shapes or include primitives, arrays, or empty objects. In practice this leaves most configuration-style maps as they are (<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#95-keyed-objects--tabular-form" target="_blank" rel="noreferrer">spec §9.5</a>).</p><h2 id="arrays" tabindex="-1">Arrays <a class="header-anchor" href="#arrays" aria-label="Permalink to &quot;Arrays&quot;">​</a></h2><p>TOON detects array structure and chooses the most efficient representation. Arrays always declare their length in brackets: <code>[N]</code>.</p><h3 id="primitive-arrays-inline" tabindex="-1">Primitive Arrays (Inline) <a class="header-anchor" href="#primitive-arrays-inline" aria-label="Permalink to &quot;Primitive Arrays (Inline)&quot;">​</a></h3><p>Arrays of primitives (strings, numbers, booleans, null) are rendered inline:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin,ops,dev</span></span></code></pre></div><p>The delimiter (comma by default) separates values. Strings containing the active delimiter must be quoted.</p><h3 id="arrays-of-objects-tabular" tabindex="-1">Arrays of Objects (Tabular) <a class="header-anchor" href="#arrays-of-objects-tabular" aria-label="Permalink to &quot;Arrays of Objects (Tabular)&quot;">​</a></h3><p>When all objects in an array share the same set of primitive-valued keys, TOON uses tabular format:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-LxE32" id="tab-4Tyl85h" checked><label data-title="Basic Tabular" for="tab-4Tyl85h">Basic Tabular</label><input type="radio" name="group-LxE32" id="tab-OhdqQoi"><label data-title="Spaces and Quoting" for="tab-OhdqQoi">Spaces and Quoting</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]{sku,qty,price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1,2,9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2,1,14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name,role}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  1,Ada Lovelace,admin</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  2,&quot;Smith, Bob&quot;,user</span></span></code></pre></div></div></div><p>The header <code>items[2]{sku,qty,price}:</code> declares:</p><ul><li><strong>Array length</strong>: <code>[2]</code> means 2 rows</li><li><strong>Field names</strong>: <code>{sku,qty,price}</code> defines the columns</li><li><strong>Active delimiter</strong>: comma (default)</li></ul><p>Each row contains values in the same order as the field list. Values are encoded as primitives (strings, numbers, booleans, null) and separated by the delimiter.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Tabular format requires identical field sets across all objects (same keys, order per object may vary), at least one key per object, and every column either primitive-valued or a uniform nested object (see below) – arrays that contain an empty <code>{}</code> element or mix value shapes within a column fall back to the expanded list form.</p></div><h3 id="nested-field-groups" tabindex="-1">Nested Field Groups <a class="header-anchor" href="#nested-field-groups" aria-label="Permalink to &quot;Nested Field Groups&quot;">​</a></h3><p>A column whose values are uniform sub-objects (same keys in every element, recursively primitive or nested-uniform) folds into the header as a nested field group, while rows stay flat:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">orders[2]{id,customer{name,country},total}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  1,Ada,DE,9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  2,Bob,FR,14.5</span></span></code></pre></div><p>The header <code>customer{name,country}</code> declares a nested-object column; each row&#39;s cells follow a depth-first walk of the field list, so <code>Ada,DE</code> fills <code>customer.name</code> and <code>customer.country</code> of the first order. Nesting depth is unbounded (<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#93-arrays-of-objects--tabular-form" target="_blank" rel="noreferrer">spec §9.3</a>).</p><h3 id="mixed-and-non-uniform-arrays" tabindex="-1">Mixed and Non-Uniform Arrays <a class="header-anchor" href="#mixed-and-non-uniform-arrays" aria-label="Permalink to &quot;Mixed and Non-Uniform Arrays&quot;">​</a></h3><p>Arrays that don&#39;t meet the tabular requirements use list format with hyphen markers:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span></span></code></pre></div><p>Each element starts with <code>- </code> at one indentation level deeper than the parent array header.</p><h3 id="objects-as-list-items" tabindex="-1">Objects as List Items <a class="header-anchor" href="#objects-as-list-items" aria-label="Permalink to &quot;Objects as List Items&quot;">​</a></h3><p>When an array element is an object, it appears as a list item:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">First</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Second</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    extra</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>When a tabular array is the first field of a list-item object, the tabular header appears on the hyphen line, with rows indented two levels deeper and other fields indented one level deeper:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[1]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      1,Ada</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      2,Bob</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">active</span></span></code></pre></div><p>When the object has only a single tabular field, the same pattern applies:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[1]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users[2]{id,name}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      1,Ada</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      2,Bob</span></span></code></pre></div><p>This is the canonical encoding for list-item objects whose first field is a tabular array.</p><h3 id="arrays-of-arrays" tabindex="-1">Arrays of Arrays <a class="header-anchor" href="#arrays-of-arrays" aria-label="Permalink to &quot;Arrays of Arrays&quot;">​</a></h3><p>When you have arrays containing primitive inner arrays:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pairs[2]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1,2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3,4</span></span></code></pre></div><p>Each inner array gets its own header on the list-item line.</p><p>When the inner arrays are themselves arrays of objects or non-uniform arrays, the same <code>- [N]:</code> header appears on the hyphen line and the nested items follow one indent deeper:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[3]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">summary</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ada</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">draft</span></span></code></pre></div><h3 id="empty-arrays" tabindex="-1">Empty Arrays <a class="header-anchor" href="#empty-arrays" aria-label="Permalink to &quot;Empty Arrays&quot;">​</a></h3><p>Empty arrays render as <code>key: []</code> for fields and <code>[]</code> at the root:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span></code></pre></div><p>The legacy <code>items[0]:</code> form is still decoded for backward compatibility.</p><h2 id="array-headers" tabindex="-1">Array Headers <a class="header-anchor" href="#array-headers" aria-label="Permalink to &quot;Array Headers&quot;">​</a></h2><h3 id="header-syntax" tabindex="-1">Header Syntax <a class="header-anchor" href="#header-syntax" aria-label="Permalink to &quot;Header Syntax&quot;">​</a></h3><p>Array headers follow this pattern:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key[N&lt;delimiter?&gt;]&lt;{fields}&gt;:</span></span></code></pre></div><p>Where:</p><ul><li><strong>N</strong> is the non-negative integer length</li><li><strong>delimiter</strong> (optional) explicitly declares the active delimiter: <ul><li>Absent → comma (<code>,</code>)</li><li><code>\\t</code> (tab character) → tab delimiter</li><li><code>|</code> → pipe delimiter</li></ul></li><li><strong>fields</strong> (optional) for tabular arrays: <code>{field1,field2,field3}</code></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The array length <code>[N]</code> helps LLMs validate structure. If you ask a model to generate TOON output, explicit lengths let you detect truncation or malformed data.</p></div><h3 id="delimiter-options" tabindex="-1">Delimiter Options <a class="header-anchor" href="#delimiter-options" aria-label="Permalink to &quot;Delimiter Options&quot;">​</a></h3><p>TOON supports three delimiters: comma (default), tab, and pipe. The delimiter is scoped to the array header that declares it.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-BJSAu" id="tab-xl98SwD" checked><label data-title="Comma (default)" for="tab-xl98SwD">Comma (default)</label><input type="radio" name="group-BJSAu" id="tab-O-4ZgMU"><label data-title="Tab" for="tab-O-4ZgMU">Tab</label><input type="radio" name="group-BJSAu" id="tab-R-vJCnd"><label data-title="Pipe" for="tab-R-vJCnd">Pipe</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2]{sku,name,qty,price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1,Widget,2,9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2,Gadget,1,14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2	]{sku	name	qty	price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1	Widget	2	9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2	Gadget	1	14.5</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">items[2|]{sku|name|qty|price}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  A1|Widget|2|9.99</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  B2|Gadget|1|14.5</span></span></code></pre></div></div></div><p>Tab and pipe delimiters are explicitly encoded in the header brackets and field braces. Inside an array scope, only the active delimiter triggers quoting – the others are literal data. Object field values (<code>key: value</code>) follow the document delimiter (§11.1) regardless of any surrounding array&#39;s active delimiter.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Tab delimiters often tokenize more efficiently than commas, especially for data with few quoted strings. Use <code>encode(data, { delimiter: &#39;\\t&#39; })</code> for additional token savings.</p></div><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><p>Decoders strip every line whose first non-space character is <code>#</code> in a lexical pre-pass, before anything else:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Server configuration</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span></span></code></pre></div><p>Comments are full-line only – a <code>#</code> anywhere else on a line is ordinary content – and decode-side only: encoders never emit them, and string values starting with <code>#</code> are always quoted so encoder output never contains a line that reads as a comment. A comment between tabular rows or entry rows does not end them (<a href="https://github.com/toon-format/spec/blob/main/SPEC.md#51-comment-lines" target="_blank" rel="noreferrer">spec §5.1</a>).</p><h2 id="quoting-and-types" tabindex="-1">Quoting and Types <a class="header-anchor" href="#quoting-and-types" aria-label="Permalink to &quot;Quoting and Types&quot;">​</a></h2><h3 id="when-strings-need-quotes" tabindex="-1">When Strings Need Quotes <a class="header-anchor" href="#when-strings-need-quotes" aria-label="Permalink to &quot;When Strings Need Quotes&quot;">​</a></h3><p>TOON quotes strings <strong>only when necessary</strong> to maximize token efficiency. A string must be quoted if:</p><ul><li>It&#39;s empty (<code>&quot;&quot;</code>)</li><li>It has leading or trailing whitespace</li><li>It equals <code>true</code>, <code>false</code>, or <code>null</code> (case-sensitive)</li><li>It looks like a number (e.g., <code>&quot;42&quot;</code>, <code>&quot;-3.14&quot;</code>, <code>&quot;1e-6&quot;</code>, <code>&quot;05&quot;</code>, <code>&quot;+1&quot;</code>)</li><li>It contains special characters: colon (<code>:</code>), quote (<code>&quot;</code>), backslash (<code>\\</code>), brackets, braces, or any control character in U+0000–U+001F</li><li>It contains the relevant delimiter (the active delimiter inside an array scope, or the document delimiter elsewhere)</li><li>It equals <code>&quot;-&quot;</code> or starts with <code>&quot;-&quot;</code> followed by any character</li><li>It equals <code>&quot;#&quot;</code> or starts with <code>&quot;#&quot;</code> (the line would read as a comment)</li></ul><p>Otherwise, strings can be unquoted. Unicode, emoji, and strings with internal (non-leading/trailing) spaces are safe unquoted:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Hello 世界 👋</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">note</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">This has inner spaces</span></span></code></pre></div><h3 id="escape-sequences" tabindex="-1">Escape Sequences <a class="header-anchor" href="#escape-sequences" aria-label="Permalink to &quot;Escape Sequences&quot;">​</a></h3><p>In quoted strings and keys, six escape sequences are valid:</p><table tabindex="0"><thead><tr><th>Character</th><th>Escape</th></tr></thead><tbody><tr><td>Backslash (<code>\\</code>)</td><td><code>\\\\</code></td></tr><tr><td>Double quote (<code>&quot;</code>)</td><td><code>\\&quot;</code></td></tr><tr><td>Newline (U+000A)</td><td><code>\\n</code></td></tr><tr><td>Carriage return (U+000D)</td><td><code>\\r</code></td></tr><tr><td>Tab (U+0009)</td><td><code>\\t</code></td></tr><tr><td>Any other U+0000–U+001F control character</td><td><code>\\uXXXX</code></td></tr></tbody></table><p>Other escapes (e.g., <code>\\x</code>, <code>\\0</code>, <code>\\b</code>) are always rejected, as are lone-surrogate <code>\\uXXXX</code> values (U+D800–U+DFFF).</p><h3 id="type-conversions" tabindex="-1">Type Conversions <a class="header-anchor" href="#type-conversions" aria-label="Permalink to &quot;Type Conversions&quot;">​</a></h3><p>Numbers are emitted in canonical decimal form for values in the §2 carve-out range; exponent notation is permitted outside. Non-JSON types (<code>NaN</code>, <code>Infinity</code>, <code>BigInt</code>, <code>Date</code>, <code>Set</code>, <code>Map</code>, <code>undefined</code>, etc.) are normalized before encoding – see <a href="/reference/api.html#type-normalization">API Reference – Type Normalization</a> for the full mapping.</p><p>Decoders accept both decimal and exponent forms on input (e.g., <code>42</code>, <code>-3.14</code>, <code>1e-6</code>), and treat tokens with forbidden leading zeros (e.g., <code>&quot;05&quot;</code>) as strings, not numbers.</p><h3 id="custom-serialization-with-tojson" tabindex="-1">Custom Serialization with toJSON <a class="header-anchor" href="#custom-serialization-with-tojson" aria-label="Permalink to &quot;Custom Serialization with toJSON&quot;">​</a></h3><p>Objects with a <code>toJSON()</code> method are serialized by calling the method and normalizing its result before encoding, similar to <code>JSON.stringify</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> obj</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  data: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;example&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  toJSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { info: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">encode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(obj)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// info: example</span></span></code></pre></div><p>The <code>toJSON()</code> method:</p><ul><li>Takes precedence over built-in normalization (Date, Array, Set, Map)</li><li>Results are recursively normalized</li><li>Is called for objects with <code>toJSON</code> in their prototype chain</li></ul><hr><p>For complete rules on quoting, escaping, type conversions, and strict-mode decoding, see <a href="https://github.com/toon-format/spec/blob/main/SPEC.md" target="_blank" rel="noreferrer">spec §2–4 (data model), §7 (strings and keys), and §14 (strict mode)</a>.</p>`,101))])}const E=i(p,[["render",h]]);export{b as __pageData,E as default};
